(function(){'use strict';
var FONT_KEY='welog-font-lock-v2',STATE_KEY='welog-pair-sheet-v4',sheet=document.getElementById('sheet'),controls=document.getElementById('controls');if(!sheet)return;
function norm(v){v=v||'';if(/^KoPub Dotum/.test(v))return'KoPub Dotum Medium';if(/^KoPub Batang/.test(v))return'KoPub Batang Medium';if(v==='Noto Sans KR')return'Noto Sans KR';if(v==='__system__')return'__system__';return'Pretendard'}
function stack(v){v=norm(v);if(v==='KoPub Dotum Medium')return'WeLogExactDotum,sans-serif';if(v==='KoPub Batang Medium')return'WeLogExactBatang,serif';if(v==='Noto Sans KR')return'WeLogExactNoto,sans-serif';if(v==='__system__')return'system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif';return'WeLogExactPretendard,sans-serif'}
function stateFont(){try{return norm((JSON.parse(localStorage.getItem(STATE_KEY)||'{}')||{}).font)}catch(e){return'Pretendard'}}function locked(){return norm(localStorage.getItem(FONT_KEY)||stateFont())}
function applyFont(v){v=norm(v||locked());document.documentElement.style.setProperty('--welog-locked-font',stack(v));sheet.style.setProperty('--welog-sheet-font',stack(v));sheet.style.setProperty('font-family','var(--welog-locked-font)','important');var sel=controls&&controls.querySelector('select[data-path="font"]');if(sel)for(var i=0;i<sel.options.length;i++)if(norm(sel.options[i].value)===v){sel.selectedIndex=i;break}}
function lock(v){v=norm(v);localStorage.setItem(FONT_KEY,v);try{var s=JSON.parse(localStorage.getItem(STATE_KEY)||'{}');s.font=v;localStorage.setItem(STATE_KEY,JSON.stringify(s))}catch(e){}applyFont(v)}
if(controls){controls.addEventListener('change',function(e){if(e.target&&e.target.matches('select[data-path="font"]'))lock(e.target.value)},true);controls.addEventListener('input',function(e){if(e.target&&e.target.matches('select[data-path="font"]'))lock(e.target.value)},true)}document.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('#tabs'))setTimeout(applyFont,20)},true);window.addEventListener('pageshow',applyFont);document.addEventListener('visibilitychange',function(){if(!document.hidden)applyFont()});applyFont();
function makeModal(){var m=document.querySelector('.welog-exact-shot');if(m)return m;m=document.createElement('div');m.className='welog-exact-shot';m.hidden=true;m.innerHTML='<section class="welog-exact-shot-dialog"><header class="welog-exact-shot-head"><div><small>PREVIEW</small><b>저장 미리보기</b></div><button type="button" aria-label="닫기">×</button></header><div class="welog-exact-shot-body"><img alt="저장 미리보기"></div></section>';document.body.appendChild(m);m.addEventListener('click',function(e){if(e.target===m||e.target.closest('.welog-exact-shot-head button'))m.hidden=true});return m}
async function ready(){applyFont();if(document.fonts&&document.fonts.ready)await document.fonts.ready;var imgs=[].slice.call(sheet.querySelectorAll('img'));await Promise.all(imgs.map(function(im){if(im.complete)return Promise.resolve();return new Promise(function(r){im.addEventListener('load',r,{once:true});im.addEventListener('error',r,{once:true});setTimeout(r,2500)})}));await new Promise(function(r){requestAnimationFrame(function(){requestAnimationFrame(r)})})}
async function shot(){if(!window.html2canvas)throw new Error('html2canvas unavailable');await ready();document.body.classList.add('welog-capturing');try{var w=Math.max(1,sheet.scrollWidth),h=Math.max(1,sheet.scrollHeight);return await window.html2canvas(sheet,{scale:2,useCORS:true,allowTaint:false,backgroundColor:'#ffffff',logging:false,imageTimeout:30000,width:w,height:h,windowWidth:Math.max(document.documentElement.clientWidth,w),windowHeight:Math.max(document.documentElement.clientHeight,h),scrollX:-window.scrollX,scrollY:-window.scrollY,onclone:function(doc){doc.body.classList.add('welog-capturing');var s=doc.getElementById('sheet');if(s){s.style.visibility='visible';s.style.opacity='1';s.style.fontFamily='var(--welog-locked-font)'}doc.querySelectorAll('.direct-bounds-overlay-fixed,.welog-layout-overlay-fixed,.welog-layout-hud,.st-toolbar,.st-resize,.st-rotate').forEach(function(n){n.style.display='none'})}})}finally{document.body.classList.remove('welog-capturing')}}
async function preview(){var m=makeModal(),img=m.querySelector('img');img.removeAttribute('src');m.hidden=false;try{var c=await shot();img.src=c.toDataURL('image/png')}catch(e){console.error('WeLog preview failed',e);m.hidden=true;alert('미리보기를 만들지 못했습니다.')}}
async function save(){var btn=document.getElementById('printBtn');if(!btn)return;var old=btn.textContent;btn.disabled=true;btn.textContent='저장 중…';try{var c=await shot(),blob=await new Promise(function(r){c.toBlob(r,'image/png')});if(!blob)throw new Error('PNG blob failed');var url=URL.createObjectURL(blob),a=document.createElement('a'),name='WeLog';try{name=((JSON.parse(localStorage.getItem(STATE_KEY)||'{}')||{}).pairName||name).trim()||name}catch(e){}a.href=url;a.download=name+'.png';document.body.appendChild(a);a.click();a.remove();setTimeout(function(){URL.revokeObjectURL(url)},3000)}catch(e){console.error('WeLog PNG failed',e);alert('PNG 저장에 실패했습니다.')}finally{btn.disabled=false;btn.textContent=old}}
function replace(id,fn){var old=document.getElementById(id);if(!old)return;var b=old.cloneNode(true);old.replaceWith(b);b.id=id;b.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();fn()},true)}replace('previewBtn',preview);replace('printBtn',save);
})();